alter function public.trip_person_activation_security_check(boolean,boolean) owner to postgres;
revoke all on function public.trip_person_activation_security_check(boolean,boolean) from public,anon,authenticated,service_role;
select public.trip_person_activation_security_check(false,false);

alter table public.trip_person_command_gate drop constraint trip_person_gate_closed;
alter table public.trip_person_command_gate add column generation bigint not null default 0
 constraint trip_person_gate_generation check(generation between 0 and 9007199254740991);
alter table public.trip_person_command_gate add constraint trip_person_gate_close_capacity check(not enabled or generation<9007199254740991);

-- The writer remains private NOLOGIN; no Member table privilege is granted to gateway.
grant select on public.journey_members to otr_trip_person_lifecycle_writer;
grant update(participation_active,participation_revision) on public.journey_members to otr_trip_person_lifecycle_writer;
create policy trip_person_activation_writer_read on public.journey_members for select to otr_trip_person_lifecycle_writer
 using(session_user='otr_trip_person_command_gateway');
create policy trip_person_activation_writer_update on public.journey_members for update to otr_trip_person_lifecycle_writer
 using(session_user='otr_trip_person_command_gateway' and coalesce((select enabled from public.trip_person_command_gate where singleton),false))
 with check(session_user='otr_trip_person_command_gateway' and coalesce((select enabled from public.trip_person_command_gate where singleton),false));
grant select on public.trip_person_command_gate to otr_trip_person_receipt_reader;
create policy trip_person_activation_reader_gate on public.trip_person_command_gate for select to otr_trip_person_receipt_reader using(true);

-- All accepted transitions, including same-state requests, advance the fence.
-- Exclusive fence is the exact lock paired with the unchanged 00600 command.
create function public.trip_person_set_command_gate(expected_generation bigint, desired_enabled boolean) returns jsonb
language plpgsql security definer set search_path=pg_catalog set lock_timeout='3s' set statement_timeout='10s'
as $$ declare g public.trip_person_command_gate; inventory_root text:=/*activation-root*/'1f6bd2cb0fe9b6a9ddbd611d78e3c8fe33de63a6676032f6d412e228b936199a'; anchor_pin text:=/*activation-anchor*/'f8fdf9394720027db4885f0127277de2a49ba046f00025e0765326746e7d25ad'; checker_pin text:=/*activation-checker*/'c5079be7b4bc04db361519c173f581e3161f8d6dccb534fbf0c982454459ca5d'; begin
 if session_user<>'postgres' or expected_generation is null or desired_enabled is null then
  raise exception 'PARTICIPATION_GATE_ADMIN_FORBIDDEN' using errcode='42501';
 end if;
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'PARTICIPATION_ISOLATION_UNSUPPORTED' using errcode='25000'; end if;
 perform pg_advisory_xact_lock(hashtextextended('otr-trip-person-activation',0));
 select * into g from public.trip_person_command_gate where singleton for update;
 if not found or g.generation is null or g.enabled is null or g.generation<0 or g.generation>9007199254740991 or g.enabled and g.generation=9007199254740991 then raise exception 'PARTICIPATION_COMMANDS_DISABLED'; end if;
 if g.generation<>expected_generation then raise exception 'PARTICIPATION_GATE_GENERATION_CONFLICT' using errcode='40001'; end if;
 if g.generation=9007199254740991 or desired_enabled and g.generation>=9007199254740990 then raise exception 'PARTICIPATION_GATE_GENERATION_EXHAUSTED'; end if;
 if desired_enabled then

  -- Full anchor definition: no payload/root/hash exclusion in the anchor itself.
  if not exists(select 1 from pg_proc pin join pg_namespace ns on ns.oid=pin.pronamespace join pg_language lang on lang.oid=pin.prolang
   where pin.oid=to_regprocedure('public.trip_person_activation_reviewed_root()')
    and ns.nspname='public' and pin.proname='trip_person_activation_reviewed_root'
    and pin.proowner='postgres'::regrole and not pin.prosecdef and pin.provolatile='i'
    and not pin.proisstrict and not pin.proleakproof and pin.prokind='f' and lang.lanname='sql'
    and pin.proconfig=array['search_path=pg_catalog']::text[]
    and encode(extensions.digest(pg_get_functiondef(pin.oid),'sha256'),'hex')=anchor_pin
    and (select count(*) from aclexplode(pin.proacl))=2
    and not exists(select 1 from aclexplode(pin.proacl) permission where permission.grantee not in ('postgres'::regrole,'otr_trip_person_receipt_reader'::regrole)
      or permission.grantor<>'postgres'::regrole or permission.privilege_type<>'EXECUTE' or permission.is_grantable)
    and not exists(select 1 from pg_roles principal where not principal.rolsuper and principal.rolname not in ('postgres','otr_trip_person_receipt_reader')
      and (has_function_privilege(principal.oid,pin.oid,'EXECUTE') or pg_has_role(principal.oid,'postgres'::regrole,'MEMBER') or pg_has_role(principal.oid,'otr_trip_person_receipt_reader'::regrole,'MEMBER')))
    and not exists(select 1 from pg_proc alias where alias.proname='trip_person_activation_reviewed_root' and alias.oid<>pin.oid)) then
   raise exception 'UNSAFE_PARTICIPATION_ACTIVATION_ANCHOR';
  end if;
  if public.trip_person_activation_reviewed_root() is distinct from inventory_root then
   raise exception 'UNSAFE_PARTICIPATION_ACTIVATION_ANCHOR_ROOT';
  end if;

  if not exists(select 1 from pg_proc p join pg_language l on l.oid=p.prolang
   where p.oid=to_regprocedure('public.trip_person_activation_security_check(boolean,boolean)')
    and p.proowner='postgres'::regrole and p.prosecdef and p.provolatile='s' and not p.proisstrict and not p.proleakproof
    and p.proconfig=array['search_path=pg_catalog']::text[] and l.lanname='plpgsql'
    and encode(extensions.digest(regexp_replace(regexp_replace(pg_get_functiondef(p.oid), E'\\$inventory\\$.*?\\$inventory\\$', '$inventory$PINNED$inventory$', 's'), E'(/\\*activation-(root|checker|anchor)\\*/)''[0-9a-f]{64}''', E'\\1''PINNED''', 'g'),'sha256'),'hex')=checker_pin
    and encode(extensions.digest(substring(p.prosrc from E'\\$inventory\\$(.*?)\\$inventory\\$')::jsonb::text,'sha256'),'hex')=inventory_root) then
   raise exception 'UNSAFE_PARTICIPATION_ACTIVATION_CHECKER';
  end if;
  perform public.trip_person_activation_security_check(true,null);
 end if;
 update public.trip_person_command_gate set enabled=desired_enabled,generation=g.generation+1 where singleton;
 return jsonb_build_object('gateClosed',not desired_enabled,'gateGeneration',g.generation+1);
end $$;
alter function public.trip_person_set_command_gate(bigint,boolean) owner to postgres;
revoke all on function public.trip_person_set_command_gate(bigint,boolean) from public,anon,authenticated,service_role,otr_trip_person_command_gateway,otr_trip_person_lifecycle_writer,otr_trip_person_receipt_reader;

create function public.trip_person_command_gate_transition_guard() returns trigger
language plpgsql security invoker set search_path=pg_catalog
as $$ declare fence bigint:=hashtextextended('otr-trip-person-activation',0); begin
 if session_user<>'postgres' or current_user<>'postgres' or tg_op<>'UPDATE'
   or not exists(select 1 from pg_locks where pid=pg_backend_pid() and locktype='advisory' and mode='ExclusiveLock' and granted
    and database=(select oid from pg_database where datname=current_database())
    and classid=((fence>>32)&4294967295)::oid and objid=(fence&4294967295)::oid and objsubid=1)
   or NEW.singleton is distinct from OLD.singleton or NEW.generation is distinct from OLD.generation+1 then
  raise exception 'PARTICIPATION_GATE_TRANSITION_INVALID' using errcode='42501';
 end if;
 return NEW;
end $$;
revoke all on function public.trip_person_command_gate_transition_guard() from public,anon,authenticated,service_role,otr_trip_person_command_gateway,otr_trip_person_lifecycle_writer,otr_trip_person_receipt_reader;
create trigger trip_person_command_gate_transition before update or delete on public.trip_person_command_gate
 for each row execute function public.trip_person_command_gate_transition_guard();

-- Fixed minimal facts only; no Actor/receipt enumeration, secrets or mutation.
create function public.trip_person_runtime_state() returns jsonb
language plpgsql stable security definer set search_path=pg_catalog
as $$ declare g public.trip_person_command_gate; inventory_root text:=/*activation-root*/'1f6bd2cb0fe9b6a9ddbd611d78e3c8fe33de63a6676032f6d412e228b936199a'; anchor_pin text:=/*activation-anchor*/'f8fdf9394720027db4885f0127277de2a49ba046f00025e0765326746e7d25ad'; checker_pin text:=/*activation-checker*/'c5079be7b4bc04db361519c173f581e3161f8d6dccb534fbf0c982454459ca5d'; begin
 if session_user<>'otr_trip_person_command_gateway' then raise exception 'REPLAY_UNAVAILABLE' using errcode='42501'; end if;

  -- Full anchor definition: no payload/root/hash exclusion in the anchor itself.
  if not exists(select 1 from pg_proc pin join pg_namespace ns on ns.oid=pin.pronamespace join pg_language lang on lang.oid=pin.prolang
   where pin.oid=to_regprocedure('public.trip_person_activation_reviewed_root()')
    and ns.nspname='public' and pin.proname='trip_person_activation_reviewed_root'
    and pin.proowner='postgres'::regrole and not pin.prosecdef and pin.provolatile='i'
    and not pin.proisstrict and not pin.proleakproof and pin.prokind='f' and lang.lanname='sql'
    and pin.proconfig=array['search_path=pg_catalog']::text[]
    and encode(extensions.digest(pg_get_functiondef(pin.oid),'sha256'),'hex')=anchor_pin
    and (select count(*) from aclexplode(pin.proacl))=2
    and not exists(select 1 from aclexplode(pin.proacl) permission where permission.grantee not in ('postgres'::regrole,'otr_trip_person_receipt_reader'::regrole)
      or permission.grantor<>'postgres'::regrole or permission.privilege_type<>'EXECUTE' or permission.is_grantable)
    and not exists(select 1 from pg_roles principal where not principal.rolsuper and principal.rolname not in ('postgres','otr_trip_person_receipt_reader')
      and (has_function_privilege(principal.oid,pin.oid,'EXECUTE') or pg_has_role(principal.oid,'postgres'::regrole,'MEMBER') or pg_has_role(principal.oid,'otr_trip_person_receipt_reader'::regrole,'MEMBER')))
    and not exists(select 1 from pg_proc alias where alias.proname='trip_person_activation_reviewed_root' and alias.oid<>pin.oid)) then
   raise exception 'UNSAFE_PARTICIPATION_ACTIVATION_ANCHOR';
  end if;
  if public.trip_person_activation_reviewed_root() is distinct from inventory_root then
   raise exception 'UNSAFE_PARTICIPATION_ACTIVATION_ANCHOR_ROOT';
  end if;

  if not exists(select 1 from pg_proc p join pg_language l on l.oid=p.prolang
   where p.oid=to_regprocedure('public.trip_person_activation_security_check(boolean,boolean)')
    and p.proowner='postgres'::regrole and p.prosecdef and p.provolatile='s' and not p.proisstrict and not p.proleakproof
    and p.proconfig=array['search_path=pg_catalog']::text[] and l.lanname='plpgsql'
    and encode(extensions.digest(regexp_replace(regexp_replace(pg_get_functiondef(p.oid), E'\\$inventory\\$.*?\\$inventory\\$', '$inventory$PINNED$inventory$', 's'), E'(/\\*activation-(root|checker|anchor)\\*/)''[0-9a-f]{64}''', E'\\1''PINNED''', 'g'),'sha256'),'hex')=checker_pin
    and encode(extensions.digest(substring(p.prosrc from E'\\$inventory\\$(.*?)\\$inventory\\$')::jsonb::text,'sha256'),'hex')=inventory_root) then
   raise exception 'UNSAFE_PARTICIPATION_ACTIVATION_CHECKER';
  end if;
 perform public.trip_person_activation_security_check(true,null);
 select * into g from public.trip_person_command_gate where singleton;
 if not found or g.generation is null or g.enabled is null or g.generation<0 or g.generation>9007199254740991 or g.enabled and g.generation=9007199254740991 then raise exception 'REPLAY_UNAVAILABLE'; end if;
 if to_regprocedure('public.trip_person_set_participation(uuid,text)') is null
   or to_regprocedure('public.trip_person_receipt_lookup(uuid,uuid,uuid)') is null then raise exception 'REPLAY_UNAVAILABLE'; end if;
 return jsonb_build_object('commandVersion',1,'receiptVersion',1,'gateClosed',not g.enabled,
   'gateGeneration',g.generation,'schemaVersion','20261005000200');
end $$;
grant otr_trip_person_receipt_reader to postgres with set true;
grant create on schema public to otr_trip_person_receipt_reader;
revoke all on function public.trip_person_runtime_state() from public,anon,authenticated,service_role,otr_trip_person_lifecycle_writer;
grant execute on function public.trip_person_runtime_state() to otr_trip_person_command_gateway;
alter function public.trip_person_runtime_state() owner to otr_trip_person_receipt_reader;
grant execute on function public.trip_person_activation_security_check(boolean,boolean) to otr_trip_person_receipt_reader;
revoke create on schema public from otr_trip_person_receipt_reader;
grant otr_trip_person_receipt_reader to postgres with set false,inherit false;

-- Fixed session defaults do not introduce LOGIN or a usable secret.
alter role otr_trip_person_command_gateway set search_path='pg_catalog';
alter role otr_trip_person_command_gateway set application_name='otr-trip-person-command-v1';
alter role otr_trip_person_command_gateway set statement_timeout='10s';
alter role otr_trip_person_command_gateway set lock_timeout='3s';
alter role otr_trip_person_command_gateway set idle_in_transaction_session_timeout='10s';
grant execute on function public.trip_person_activation_reviewed_root() to otr_trip_person_receipt_reader;
select public.trip_person_activation_security_check(true,false);
commit;
